android.extraProguardRules:
# General Optimization and Deobfuscation Attributes
-keepattributes SourceFile,LineNumberTable
-keepattributes *Annotation*
-keepattributes Signature
-keepattributes InnerClasses,EnclosingMethod

# Suppress harmless build-time warnings for optional dependencies
-dontwarn javax.annotation.**
-dontwarn org.checkerframework.**
-dontwarn okhttp3.**
-dontwarn okio.**

# React Native & Hermes
-keep class com.facebook.hermes.unicode.** { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.bridge.** { *; }

# Sentry
-dontwarn io.sentry.**
-keep class io.sentry.** { *; }

# Google Play Billing (expo-iap)
-keep class com.android.billingclient.api.** { *; }
-keep class expo.modules.iap.** { *; }

# Google Mobile Ads / AdMob & UMP
-keep class com.google.android.gms.ads.** { *; }
-keep class com.google.android.ump.** { *; }
-keep class io.invertase.googlemobileads.** { *; }
-dontwarn io.invertase.googlemobileads.**

# Health Connect
-keep class androidx.health.connect.client.** { *; }
-keep class dev.matinzd.healthconnect.** { *; }

# Google Play Integrity (expo-app-integrity)
-keep class com.google.android.play.core.integrity.** { *; }
-keep class expo.modules.integrity.** { *; }

# Camera & Image Picker
-keep class androidx.camera.** { *; }
-keep class expo.modules.camera.** { *; }
-keep class expo.modules.imagepicker.** { *; }

# Web Browser / Custom Tabs (Google OAuth)
-keep class androidx.browser.customtabs.** { *; }
-keep class expo.modules.webbrowser.** { *; }

# Nitro Modules & MMKV
-keep class com.margelo.nitro.** { *; }
-keep class com.tencent.mmkv.** { *; }

# Reanimated & Worklets & Screens
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
-keep class com.swmansion.rnscreens.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
